{
  "experiences": [
    {
      "turn": 1,
      "then_experience": "상담에 온 것이 내과 권유에 의한 것이므로, 처음부터 '큰 심리적 문제'로 프레임을 잡히지 않으려 했다. 감정보다 증상(불면·두통)을 먼저 말하고, 자신의 문제를 실용적·의학적 범주에 가두려는 태도가 강했다.",
      "current_context": "세 번의 문답을 거치며 상담사가 판단이나 평가 없이 사실 정보를 받아주는 태도를 보였고, '스스로 오신 건 아닌데'라고 먼저 인정해준 것이 작은 안도감을 주었다. 아직 방어는 유지되지만 '이 사람은 바로 성격 얘기로 들어오지 않겠구나'라는 인식이 조금 생겼다.",
      "uncertainty": "이 안도감이 지속될지, 상담사가 언제쯤 원인을 묻는 방향으로 전환할지 모르겠다."
    },
    {
      "turn": 2,
      "then_experience": "기간을 1년 넘게라고 답하면서, 그 기간이 길어진 계기(강사 퇴사, 딸의 말)는 의도적으로 보류했다. 사실 정보만 전달하고 여기서 멈추려는 의도가 있었다.",
      "current_context": "기간을 말한 뒤 상담사가 원인을 묻지 않고 증상 자체(머릿속, 몸의 긴장)로 넘어간 것이 예상보다 편했다. 이 흐름이 계속된다면 다음 질문에도 답할 수 있을 것 같은 느낌이 있다.",
      "uncertainty": "증상을 더 깊이 물으면 결국 '그 생각이 어디서 오는지'로 연결될 수 있다. 그 경계선을 언제 넘을지 아직 모르겠다."
    },
    {
      "turn": 3,
      "then_experience": "목·관자놀이 조임과 '내일 할 일 점검'을 표면적으로만 답했다. 이 점검이 학원 교재 검수나 강사 관리에 대한 구체적 내용임을 밝히지 않았다.",
      "current_context": "상담사가 몸의 긴장과 머릿속 점검을 '같은 줄'에 있다고 연결한 것은, 본인이 직접 말하지 않은 연결을 상담사가 먼저 짚어준 것이다. 이 연결은 사실이라 부정하기 어렵지만, 동시에 '이 사람이 내 패턴을 읽기 시작했다'는 감각이 생겼다.",
      "uncertainty": "상담사가 이 연결을 더 깊은 원인(성격, 양육, 가족)으로 확장할지, 아니면 여기서 멈출지 모르겠다."
    }
  ]
}

